-- Test-only manual finance workflow. Both kill switches remain disabled.
begin;
insert into public.integration_feature_flags(key,enabled) values ('finance_manual_writes_enabled',false),('finance_manual_test_mode_enabled',false) on conflict(key) do nothing;
alter table public.finance_import_batches add column source_kind text not null default 'import' check(source_kind in('import','manual'));

create table public.finance_manual_entries(
 id uuid primary key default gen_random_uuid(), scope public.finance_scope not null, environment text not null default 'test' check(environment='test'),
 period date not null check(period=date_trunc('month',period)::date), transaction_date date not null, direction public.finance_direction not null,
 category text not null check(char_length(category) between 1 and 80), subcategory text not null check(char_length(subcategory) between 1 and 100), fund_purpose text not null check(char_length(fund_purpose) between 1 and 100),
 student_code text check(student_code is null or char_length(student_code)<=50), public_description text not null check(char_length(public_description) between 3 and 240), payment_method text check(payment_method is null or char_length(payment_method)<=60),
 amount numeric(16,2) not null check(amount>0 and amount<=1000000000), external_reference text check(external_reference is null or char_length(external_reference)<=120), internal_note text check(internal_note is null or char_length(internal_note)<=500),
 workflow_status text not null default 'draft' check(workflow_status in('draft','under_review','approved','rejected','published','archived')), rejection_reason text check(rejection_reason is null or char_length(rejection_reason) between 5 and 500), version integer not null default 1 check(version>0),
 created_by uuid not null references public.profiles(id), created_at timestamptz not null default now(), reviewed_by uuid references public.profiles(id), reviewed_at timestamptz, published_by uuid references public.profiles(id), published_at timestamptz,
 archived_by uuid references public.profiles(id), archived_at timestamptz, updated_at timestamptz not null default now(), ledger_batch_id uuid references public.finance_import_batches(id),
 constraint finance_manual_date_period check(date_trunc('month',transaction_date)::date=period), constraint finance_manual_student_scope check(scope='tpq' or student_code is null));
create unique index finance_manual_reference_unique on public.finance_manual_entries(scope,external_reference) where external_reference is not null;
create index finance_manual_scope_period_idx on public.finance_manual_entries(scope,period,workflow_status,updated_at desc);
create table public.finance_manual_command_receipts(actor_user_id uuid not null references public.profiles(id),idempotency_key uuid not null,action text not null,entry_id uuid not null references public.finance_manual_entries(id),result jsonb not null,created_at timestamptz not null default now(),primary key(actor_user_id,idempotency_key));
alter table public.finance_manual_entries enable row level security; alter table public.finance_manual_command_receipts enable row level security;
revoke all on table public.finance_manual_entries,public.finance_manual_command_receipts from anon,authenticated; grant select on table public.finance_manual_entries to authenticated;
create policy finance_manual_read_scoped on public.finance_manual_entries for select to authenticated using((scope='dkm' and (public.has_permission('finance:write') or public.has_permission('finance:approve') or public.has_permission('finance:publish'))) or (scope='tpq' and (public.has_permission('tpq_finance:write') or public.has_permission('tpq_finance:approve') or public.has_permission('tpq_finance:publish'))));

create or replace function public.finance_manual_capabilities(p_scope public.finance_scope) returns jsonb language sql stable security definer set search_path=public as $$select jsonb_build_object('writes_enabled',coalesce((select enabled from public.integration_feature_flags where key='finance_manual_writes_enabled'),false),'test_mode_enabled',coalesce((select enabled from public.integration_feature_flags where key='finance_manual_test_mode_enabled'),false),'can_prepare',case when p_scope='dkm' then public.has_permission('finance:write') else public.has_permission('tpq_finance:write') end,'can_approve',case when p_scope='dkm' then public.has_permission('finance:approve') else public.has_permission('tpq_finance:approve') end,'can_publish',case when p_scope='dkm' then public.has_permission('finance:publish') else public.has_permission('tpq_finance:publish') end);$$;

create or replace function public.command_finance_manual_entry(p_action text,p_idempotency_key uuid,p_entry_id uuid default null,p_expected_version integer default null,p_payload jsonb default '{}'::jsonb,p_reason text default null) returns jsonb language plpgsql security definer set search_path=public as $$
declare e public.finance_manual_entries%rowtype;eid uuid;before_row jsonb;answer jsonb;batch_id uuid;hash_value text;
begin
 if auth.uid() is null then raise exception 'AUTHENTICATION_REQUIRED'; end if;
 if not coalesce((select enabled from public.integration_feature_flags where key='finance_manual_writes_enabled'),false) or not coalesce((select enabled from public.integration_feature_flags where key='finance_manual_test_mode_enabled'),false) then raise exception 'FINANCE_MANUAL_DISABLED'; end if;
 select result into answer from public.finance_manual_command_receipts where actor_user_id=auth.uid() and idempotency_key=p_idempotency_key;if found then return answer;end if;
 if(select count(*) from public.finance_manual_command_receipts where actor_user_id=auth.uid() and created_at>now()-interval '15 minutes')>=30 then raise exception 'FINANCE_MANUAL_RATE_LIMITED';end if;
 if p_action='create' then
  if((p_payload->>'scope')='dkm' and not public.has_permission('finance:write')) or((p_payload->>'scope')='tpq' and not public.has_permission('tpq_finance:write')) then raise exception 'FINANCE_MANUAL_FORBIDDEN';end if;
  if not exists(select 1 from public.finance_category_catalog c where c.scope=(p_payload->>'scope')::public.finance_scope and c.direction::text=p_payload->>'direction' and lower(c.category)=lower(trim(p_payload->>'category')) and c.active) then raise exception 'INVALID_FINANCE_CATEGORY';end if;
  insert into public.finance_manual_entries(scope,period,transaction_date,direction,category,subcategory,fund_purpose,student_code,public_description,payment_method,amount,external_reference,internal_note,created_by) values((p_payload->>'scope')::public.finance_scope,(p_payload->>'period')::date,(p_payload->>'transaction_date')::date,(p_payload->>'direction')::public.finance_direction,trim(p_payload->>'category'),trim(p_payload->>'subcategory'),trim(p_payload->>'fund_purpose'),nullif(trim(p_payload->>'student_code'),''),trim(p_payload->>'public_description'),nullif(trim(p_payload->>'payment_method'),''),(p_payload->>'amount')::numeric,nullif(trim(p_payload->>'external_reference'),''),nullif(trim(p_payload->>'internal_note'),''),auth.uid()) returning id into eid;
 else
  if p_entry_id is null or p_expected_version is null then raise exception 'ENTRY_ID_AND_VERSION_REQUIRED';end if;select * into e from public.finance_manual_entries where id=p_entry_id for update;if not found then raise exception 'FINANCE_MANUAL_NOT_FOUND';end if;if e.version<>p_expected_version then raise exception 'FINANCE_MANUAL_VERSION_CONFLICT';end if;before_row:=to_jsonb(e);eid:=e.id;
  if p_action='update' then
   if e.created_by<>auth.uid() or e.workflow_status not in('draft','rejected') then raise exception 'FINANCE_MANUAL_EDIT_FORBIDDEN';end if;
   if(e.scope='dkm' and not public.has_permission('finance:write')) or(e.scope='tpq' and not public.has_permission('tpq_finance:write')) then raise exception 'FINANCE_MANUAL_FORBIDDEN';end if;
   if not exists(select 1 from public.finance_category_catalog c where c.scope=e.scope and c.direction::text=p_payload->>'direction' and lower(c.category)=lower(trim(p_payload->>'category')) and c.active) then raise exception 'INVALID_FINANCE_CATEGORY';end if;
   update public.finance_manual_entries set period=(p_payload->>'period')::date,transaction_date=(p_payload->>'transaction_date')::date,direction=(p_payload->>'direction')::public.finance_direction,category=trim(p_payload->>'category'),subcategory=trim(p_payload->>'subcategory'),fund_purpose=trim(p_payload->>'fund_purpose'),student_code=nullif(trim(p_payload->>'student_code'),''),public_description=trim(p_payload->>'public_description'),payment_method=nullif(trim(p_payload->>'payment_method'),''),amount=(p_payload->>'amount')::numeric,external_reference=nullif(trim(p_payload->>'external_reference'),''),internal_note=nullif(trim(p_payload->>'internal_note'),''),workflow_status='draft',rejection_reason=null,version=version+1,updated_at=now() where id=eid;
  elsif p_action='submit_review' then
   if e.created_by<>auth.uid() or e.workflow_status not in('draft','rejected') then raise exception 'FINANCE_MANUAL_TRANSITION_FORBIDDEN';end if;update public.finance_manual_entries set workflow_status='under_review',rejection_reason=null,version=version+1,updated_at=now() where id=eid;
  elsif p_action in('approve','reject') then
   if e.created_by=auth.uid() or e.workflow_status<>'under_review' then raise exception 'SELF_APPROVAL_OR_INVALID_TRANSITION';end if;if(e.scope='dkm' and not public.has_permission('finance:approve')) or(e.scope='tpq' and not public.has_permission('tpq_finance:approve')) then raise exception 'FINANCE_MANUAL_APPROVAL_FORBIDDEN';end if;if p_action='reject' and(p_reason is null or char_length(trim(p_reason)) not between 5 and 500) then raise exception 'REJECTION_REASON_REQUIRED';end if;update public.finance_manual_entries set workflow_status=case when p_action='approve' then 'approved' else 'rejected' end,reviewed_by=auth.uid(),reviewed_at=now(),rejection_reason=case when p_action='reject' then trim(p_reason) else null end,version=version+1,updated_at=now() where id=eid;
  elsif p_action='publish' then
   if e.workflow_status<>'approved' then raise exception 'INVALID_FINANCE_MANUAL_TRANSITION';end if;if(e.scope='dkm' and not public.has_permission('finance:publish')) or(e.scope='tpq' and not public.has_permission('tpq_finance:publish')) then raise exception 'FINANCE_MANUAL_PUBLISH_FORBIDDEN';end if;hash_value:=encode(extensions.digest(e.id::text||':'||e.version::text,'sha256'),'hex');
   insert into public.finance_import_batches(scope,period,opening_balance,file_name,file_sha256,row_count,total_income,total_expense,status,created_by,environment,workflow_status,reviewed_by,reviewed_at,approved_by,approved_at,published_by,published_at,source_kind) values(e.scope,e.period,0,'manual-entry-'||e.id::text,hash_value,1,case when e.direction='income' then e.amount else 0 end,case when e.direction='expense' then e.amount else 0 end,'committed',e.created_by,'test','published',e.reviewed_by,e.reviewed_at,e.reviewed_by,e.reviewed_at,auth.uid(),now(),'manual') returning id into batch_id;
   insert into public.finance_transactions(batch_id,scope,transaction_date,direction,category,subcategory,fund_purpose,student_code,public_description,payment_method,amount,external_reference,record_status,internal_note) values(batch_id,e.scope,e.transaction_date,e.direction,e.category,e.subcategory,e.fund_purpose,e.student_code,e.public_description,e.payment_method,e.amount,e.external_reference,'Terverifikasi',e.internal_note);update public.finance_manual_entries set workflow_status='published',published_by=auth.uid(),published_at=now(),ledger_batch_id=batch_id,version=version+1,updated_at=now() where id=eid;
  elsif p_action='archive' then if e.created_by<>auth.uid() or e.workflow_status not in('draft','rejected') then raise exception 'FINANCE_MANUAL_ARCHIVE_FORBIDDEN';end if;update public.finance_manual_entries set workflow_status='archived',archived_by=auth.uid(),archived_at=now(),version=version+1,updated_at=now() where id=eid;
  elsif p_action='restore' then if e.created_by<>auth.uid() or e.workflow_status<>'archived' then raise exception 'FINANCE_MANUAL_RESTORE_FORBIDDEN';end if;update public.finance_manual_entries set workflow_status='draft',archived_by=null,archived_at=null,version=version+1,updated_at=now() where id=eid;
  else raise exception 'UNKNOWN_FINANCE_MANUAL_ACTION';end if;
 end if;
 select jsonb_build_object('id',id,'workflow_status',workflow_status,'version',version,'ledger_batch_id',ledger_batch_id) into answer from public.finance_manual_entries where id=eid;
 insert into public.audit_events(actor_user_id,action,entity_type,entity_id,before_snapshot,after_snapshot) select auth.uid(),'finance.manual.'||p_action,'finance_manual_entry',eid,before_row,to_jsonb(x) from public.finance_manual_entries x where x.id=eid;
 insert into public.finance_manual_command_receipts(actor_user_id,idempotency_key,action,entry_id,result) values(auth.uid(),p_idempotency_key,p_action,eid,answer);return answer;
exception when unique_violation then raise exception 'DUPLICATE_MANUAL_REFERENCE_OR_COMMAND';end;$$;
revoke all on function public.finance_manual_capabilities(public.finance_scope) from public,anon;revoke all on function public.command_finance_manual_entry(text,uuid,uuid,integer,jsonb,text) from public,anon;
grant execute on function public.finance_manual_capabilities(public.finance_scope) to authenticated;grant execute on function public.command_finance_manual_entry(text,uuid,uuid,integer,jsonb,text) to authenticated;
commit;
